<body>
  <header class="masthead page-width">
    <div class="brand"><span class="brand-mark" aria-hidden="true"></span>FIELD NOTES</div>
    <nav aria-label="Main navigation">
      <a href="#work">Work</a>
      <a href="#about">About</a>
      <a href="mailto:studio@example.test">Contact</a>
    </nav>
  </header>
  <main class="page-width">
    <section class="hero" aria-labelledby="hero-title">
      <h1 id="hero-title"><span>Make room for</span> <span>the moving world.</span></h1>
      <div class="hero-details">
        <p>Thoughtful films, clear stories, lasting places.</p>
        <a class="primary" href="#work">Explore the work<svg class="arrow" viewBox="0 0 24 24" fill="none" aria-hidden="true"><path d="M4 12h15m-6-6 6 6-6 6" stroke="currentColor" stroke-width="1.5"/></svg></a>
      </div>
      <div class="film" data-media>
        <img src="assets/poster.svg" alt="" width="960" height="540" fetchpriority="high">
        <video src="assets/scene.webm" poster="assets/poster.svg" muted playsinline loop preload="none" aria-hidden="true" tabindex="-1" hidden></video>
        <button class="media-toggle" type="button" aria-label="Play background video" hidden>
          <svg class="pause-icon" viewBox="0 0 20 20" fill="currentColor" aria-hidden="true"><path d="M5 3h3v14H5zm7 0h3v14h-3z"/></svg>
          <svg class="play-icon" viewBox="0 0 20 20" fill="currentColor" aria-hidden="true"><path d="m6 3 11 7-11 7z"/></svg>
        </button>
        <span class="sr-only" role="status" data-media-status></span>
      </div>
    </section>
    <section class="work" id="work" aria-labelledby="work-title">
      <h2 id="work-title">Selected work</h2>
      <ul class="work-list">
        <li><span>Tidal study</span><span class="work-year">/ 2026</span></li>
        <li><span>Mountain light</span><span class="work-year">/ 2025</span></li>
      </ul>
    </section>
    <section class="about" id="about" aria-label="About">
      <p>An independent film practice.</p>
    </section>
  </main>
  <script>
    (() => {
      const root = document.querySelector('"'[data-media]');
      const video = root.querySelector('video');
      const button = root.querySelector('button');
      const status = root.querySelector('[data-media-status]');
      const reduce = window.matchMedia('(prefers-reduced-motion: reduce)');
      let visible = false;
      let userPaused = false;
      let blocked = false;
      let disposed = false;
      let epoch = 0;
      const controller = new AbortController();
      const options = { signal: controller.signal };
      const setControl = (playing) => {
        button.dataset.playing = String(playing);
        button.setAttribute('aria-label', playing ? 'Pause background video' : 'Play background video');
      };
      const still = () => {
        epoch++;
        video.pause();
        video.hidden = true;
        setControl(false);
      };
      const sync = async () => {
        button.hidden = reduce.matches;
        if (disposed || "'!visible || userPaused || blocked || reduce.matches || document.hidden) {
          still();
          return;
        }
        const attempt = ++epoch;
        try {
          await video.play();
          if (attempt !== epoch) return;
          video.hidden = false;
          setControl(true);
          status.textContent = '"'';
        } catch {
          if (attempt "'!== epoch) return;
          blocked = true;
          still();
          status.textContent = '"'Static preview: playback unavailable.';
        }
      };
      let observer;
      try {
        if ("'!('"'IntersectionObserver' in window)) return;
        video.muted = true;
        video.playsInline = true;
        button.addEventListener('click', () => {
          userPaused = "'!video.paused;
          blocked = false;
          sync();
        }, options);
        video.addEventListener('"'error', () => {
          blocked = true;
          still();
          status.textContent = 'Static preview: media unavailable.';
        }, options);
        reduce.addEventListener('change', sync, options);
        document.addEventListener('visibilitychange', sync, options);
        observer = new IntersectionObserver(([entry]) => {
          visible = entry.isIntersecting;
          sync();
        }, { threshold: 0 });
        observer.observe(root);
        const dispose = () => {
          disposed = true;
          still();
          observer.disconnect();
          controller.abort();
        };
        window.addEventListener('pagehide', (event) => {
          if (event.persisted) { visible = false; still(); }
          else dispose();
        }, options);
        window.addEventListener('pageshow', (event) => {
          if (event.persisted) {
            const rect = root.getBoundingClientRect();
            visible = rect.bottom > 0 && rect.top < window.innerHeight;
            sync();
          }
        }, options);
      } catch {
        still();
        button.hidden = true;
        observer?.disconnect();
        controller.abort();
      }
    })();
  </script>
</body>
</html>
